// Writes worker/migrations/0006_people.sql from setup/data/people.json (made by seed-people.mjs):
// the canonical facilitators and the per-batch group-leader lists, plus the columns that hold each devotee's choice.
import fs from 'node:fs';
import P from './data/people.json' with { type: 'json' };
const sq = v => `'${String(v).replace(/'/g, "''")}'`;
const sql = [
  '-- Decision 33: facilitator and group leader are picked from lists, never typed (generated by setup/build-people-sql.mjs).',
  'CREATE TABLE facilitators ("name" TEXT PRIMARY KEY, "in_cohort" INTEGER NOT NULL DEFAULT 0, "order" INTEGER NOT NULL);',
  'CREATE TABLE group_leaders ("batch_id" TEXT NOT NULL, "name" TEXT NOT NULL, "active" INTEGER NOT NULL DEFAULT 1, "merged" TEXT NOT NULL DEFAULT \'\', "order" INTEGER NOT NULL, PRIMARY KEY ("batch_id", "name"));',
  "ALTER TABLE accounts ADD COLUMN requested_facilitator TEXT NOT NULL DEFAULT '';",
  "ALTER TABLE accounts ADD COLUMN requested_group_leader TEXT NOT NULL DEFAULT '';",
  "ALTER TABLE memberships ADD COLUMN facilitator TEXT NOT NULL DEFAULT '';",
  ...P.facilitators.map((f, i) => `INSERT INTO facilitators ("name", "in_cohort", "order") VALUES (${sq(f.name)}, ${f.inCohort ? 1 : 0}, ${i + 1});`),
  ...Object.entries(P.leaders).flatMap(([b, list]) => list.map((l, i) =>
    `INSERT INTO group_leaders ("batch_id", "name", "merged", "order") VALUES (${sq(b)}, ${sq(l.name)}, ${sq(l.merged.join('; '))}, ${i + 1});`)),
  "UPDATE mirror_state SET dirty = dirty + 1 WHERE tbl IN ('accounts', 'memberships');"
];
fs.writeFileSync(new URL('../worker/migrations/0006_people.sql', import.meta.url), sql.join('\n') + '\n');
console.log(`0006_people.sql: ${P.facilitators.length} facilitators, ${Object.values(P.leaders).flat().length} group leaders`);
